import{_ as t,c as e,o as r,a}from"./app.9a45957d.js";const u=JSON.parse('{"title":"Content strategy overview","description":"","frontmatter":{},"headers":[{"level":2,"title":"Positioning","slug":"positioning","link":"#positioning","children":[]},{"level":2,"title":"Audience segments (summary)","slug":"audience-segments-summary","link":"#audience-segments-summary","children":[]},{"level":2,"title":"Content pillars (mix guide)","slug":"content-pillars-mix-guide","link":"#content-pillars-mix-guide","children":[]},{"level":2,"title":"Format mix (examples)","slug":"format-mix-examples","link":"#format-mix-examples","children":[]},{"level":2,"title":"Related pages","slug":"related-pages","link":"#related-pages","children":[]}],"relativePath":"replybridge/marketing/content-strategy.md"}'),s={name:"replybridge/marketing/content-strategy.md"},n=a('<h1 id="content-strategy-overview" tabindex="-1">Content strategy overview <a class="header-anchor" href="#content-strategy-overview" aria-hidden="true">#</a></h1><p>A concise plan to turn ReplyBridge’s official channels (especially Instagram) into <strong>saves, profile visits, and installs</strong>. For full copy and PNG specs, see reply-bridge <code>marketing/STRATEGY.md</code>.</p><hr><h2 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-hidden="true">#</a></h2><blockquote><p>An app that turns Instagram comment and DM responses into a <strong>clean, automated official path</strong>.</p></blockquote><ul><li><strong>Audience:</strong> Teams that run Instagram <strong>business or creator</strong> accounts <strong>solo or with a small crew</strong>.</li><li><strong>Differentiation:</strong> Meta <strong>official APIs</strong> (Private Reply, Comments API), <strong>per-post automation window</strong>, <strong>keywords</strong> and <strong>once-per-user</strong> rules to reduce spam.</li><li><strong>Tone:</strong> Editorial, spacious typography—<em>Digital Curator</em>—not hype or emoji overload.</li></ul><hr><h2 id="audience-segments-summary" tabindex="-1">Audience segments (summary) <a class="header-anchor" href="#audience-segments-summary" aria-hidden="true">#</a></h2><table><thead><tr><th>Segment</th><th>Core message</th></tr></thead><tbody><tr><td>Solo creators (~5k–100k)</td><td>“From comment to DM—automatically.”</td></tr><tr><td>One-person ecommerce / SMB</td><td>“Keywords + once per user—no spam.”</td></tr><tr><td>Agency / brand manager</td><td>“Per-post sends and reach you can report.”</td></tr></tbody></table><p>Start with creators and SMB; expand report-style content later.</p><hr><h2 id="content-pillars-mix-guide" tabindex="-1">Content pillars (mix guide) <a class="header-anchor" href="#content-pillars-mix-guide" aria-hidden="true">#</a></h2><table><thead><tr><th>Code</th><th>Name</th><th>Role</th><th>Mix (guide)</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>Teach</td><td>Explain Private Reply, keywords, windows</td><td>~30%</td></tr><tr><td><strong>F2</strong></td><td>Use case</td><td>Launches, events, real scenarios</td><td>~25%</td></tr><tr><td><strong>F3</strong></td><td>Product</td><td>Feature highlights, UI tips</td><td>~20%</td></tr><tr><td><strong>F4</strong></td><td>Proof</td><td>Testimonials, stats screenshots, quotes</td><td>~15%</td></tr><tr><td><strong>F5</strong></td><td>Community</td><td>Q&amp;A, lessons learned, roadmap polls</td><td>~10%</td></tr></tbody></table><hr><h2 id="format-mix-examples" tabindex="-1">Format mix (examples) <a class="header-anchor" href="#format-mix-examples" aria-hidden="true">#</a></h2><table><thead><tr><th>Format</th><th>Goal</th></tr></thead><tbody><tr><td>Vertical multi-slide feed posts</td><td>Saves &amp; shares</td></tr><tr><td>Short Reels (screen capture, before/after)</td><td>Reach</td></tr><tr><td>Square single-image posts</td><td>Product shots &amp; reviews</td></tr><tr><td>Stories</td><td>Q&amp;A, links, cross-promotion</td></tr></tbody></table><p>Post when your audience is likely scrolling (e.g. weekday mornings/evenings) and refine with data.</p><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-hidden="true">#</a></h2><ul><li><a href="/replybridge/marketing/">Marketing hub</a></li><li><a href="/replybridge/marketing/tips">Practical tips</a></li><li><a href="/replybridge/marketing/series-overview">Card series guide</a></li></ul>',20),o=[n];function i(d,l,g,c,h,m){return r(),e("div",null,o)}const y=t(s,[["render",i]]);export{u as __pageData,y as default};
